def build_messages(user_prompt, thinking):
    system = {"role": "system", "content": "You are a concise assistant."}
    content = user_prompt if thinking else user_prompt + " /no_think"
    user = {"role": "user", "content": content}
    return [system, user]

msgs = build_messages("What is 2+2?", False)
print(msgs[1]["content"])
